BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='15s';
DO $reviewed$ DECLARE b zoi.listings;a zoi.listings;r jsonb;point jsonb;BEGIN
 IF (SELECT encode(extensions.digest(prosrc,'sha256'),'hex') FROM pg_proc WHERE oid='public.geography_review_apply(uuid,uuid,text,text,jsonb)'::regprocedure) IS DISTINCT FROM '196349acadaf3fb6894b28ec20419f923a216293af32ea03c84be5cfb147081e'
 OR (SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE oid='public.geography_review_apply(uuid,uuid,text,text,jsonb)'::regprocedure) IS DISTINCT FROM 'postgres'
 OR (SELECT prosecdef FROM pg_proc WHERE oid='public.geography_review_apply(uuid,uuid,text,text,jsonb)'::regprocedure) IS DISTINCT FROM true
 OR (SELECT proconfig FROM pg_proc WHERE oid='public.geography_review_apply(uuid,uuid,text,text,jsonb)'::regprocedure) IS DISTINCT FROM ARRAY['search_path=""']::text[]
 OR (SELECT proacl FROM pg_proc WHERE oid='public.geography_review_apply(uuid,uuid,text,text,jsonb)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,service_role=X/postgres}'::aclitem[] THEN RAISE EXCEPTION 'installed_geography_writer_changed';END IF;
 SELECT * INTO STRICT b FROM zoi.listings WHERE id='eed95c0e-ef1d-4376-9335-418b56227e99'::uuid FOR UPDATE;
