 SELECT * INTO STRICT a FROM zoi.listings WHERE id=b.id;
 IF (to_jsonb(a)-ARRAY['latitude','longitude','geo_precision','profile','updated_at']) IS DISTINCT FROM (to_jsonb(b)-ARRAY['latitude','longitude','geo_precision','profile','updated_at'])
 OR (coalesce(a.profile,'{}'::jsonb)-'_geo') IS DISTINCT FROM (coalesce(b.profile,'{}'::jsonb)-'_geo') THEN RAISE EXCEPTION 'protected_listing_fields_changed';END IF;
 IF r->>'ok' IS DISTINCT FROM 'true' OR r->>'request_id' IS DISTINCT FROM '20e503d8-7879-482c-9fac-38875684337d' OR r->>'listing_id' IS DISTINCT FROM b.id::text OR r->>'report_sha256' IS DISTINCT FROM '98cd598848399a1169cedb3126a348860389da747f9a57bbcca26a50fc9ef104'
 OR a.latitude IS DISTINCT FROM -33.8818077::double precision OR a.longitude IS DISTINCT FROM 151.2192239::double precision OR a.geo_precision IS DISTINCT FROM 'street'
 OR r->>'after_snapshot' IS DISTINCT FROM zoi.geography_fingerprint(a) THEN RAISE EXCEPTION 'geography_receipt_mismatch';END IF;
 IF public.geography_review_apply('20e503d8-7879-482c-9fac-38875684337d'::uuid,'eed95c0e-ef1d-4376-9335-418b56227e99'::uuid,'f01a53599068c3e3b7ff6abbe93fbdee','{"candidate":{"address":{"city":"Paddington","country":"Australia","postal_code":"2021","region":"NSW","street":"1 Oxford Street"},"capture_sha256":"4bc9d31298e3ce5c06c83e02e1886490f95311623af246ffaaaaaa46cff59257","contact_card_sha256":"c9e2ecf07036609d9ee90cf70cda0a99ba00078c9b3a27104ecc6393f4da2963","destination_locality":{"east":151.2376219544052,"north":-33.876779430730046,"source_url":"https://maps.six.nsw.gov.au/arcgis/rest/services/public/NSW_Administrative_Boundaries/MapServer/0","south":-33.88990972456109,"west":151.21818568826185},"evidence_kind":"reviewed_named_place_shortlink","evidence_url":"https://www.google.com/maps/place/25hours+Hotel+Sydney+The+Olympia/@-33.8818077,151.2192239,17z/data=!4m9!3m8!1s0x6b12ad1a2707c6d3:0x8f530e60394b643c!5m2!4m1!1i2!8m2!3d-33.8818077!4d151.2192239!16s%2Fg%2F11ydb23jl9?entry=tts&g_ep=EgoyMDI1MTAyNy4wIPu8ASoASAFQAw%3D%3D&skid=8525742f-6776-48f8-8220-9e5dcdad2ca1","latitude":-33.8818077,"longitude":151.2192239,"name":"25hours Hotel Sydney The Olympia","place_id":"0x6b12ad1a2707c6d3:0x8f530e60394b643c","precision":"source_published","shortlink_url":"https://maps.app.goo.gl/pjr7PLgGhUaPMLKQ7"},"coordinate_writes":0,"http_status":200,"identity_review_sha256":"3b6ed69c760be5b61478f2208e5d6769e85a2c4ec46f7a6920ebdb8ed461f2c2","kind":"official_coordinate_dry_run","listing_id":"eed95c0e-ef1d-4376-9335-418b56227e99","provider_calls":0,"reason":"coordinate_plausibility_review_required","schema":1,"snapshot_sha256":"f959023d0c4c18ee44831d5dce138608797911b743831d4442ffdfec7b4cf3dd","source_fingerprint":"a806c69ce922044b022918f9394aafe8","source_sha256":"8a5bfc680ed075910fa554c72a09864473a512846178dc47009c8330bd56957f","source_url":"https://25hours-hotels.com/en/contact/","status":"review_required"}','{"official_source_confirmed":true,"stored_address":"1 Oxford Street, Paddin