 point:=public.geography_reviewed_point(b.id);
 IF point IS NULL OR (point->>'latitude')::double precision IS DISTINCT FROM a.latitude OR (point->>'longitude')::double precision IS DISTINCT FROM a.longitude THEN RAISE EXCEPTION 'public_point_missing';END IF;
 IF NOT EXISTS(SELECT 1 FROM zoi.geography_reviews WHERE request_id='20e503d8-7879-482c-9fac-38875684337d'::uuid AND receipt=r AND after_fingerprint=zoi.geography_fingerprint(a)) THEN RAISE EXCEPTION 'private_receipt_missing';END IF;
