COMMIT;
SELECT id,name,md5(to_jsonb(l)::text) current_row_hash,latitude,longitude,geo_precision,public.geography_reviewed_point(id) public_point,(SELECT count(*) FROM zoi.geography_reviews) ledger_count,EXISTS(SELECT 1 FROM zoi.geography_reviews WHERE request_id='20e503d8-7879-482c-9fac-38875684337d'::uuid) request_installed FROM zoi.listings l WHERE id='eed95c0e-ef1d-4376-9335-418b56227e99'::uuid;
